"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[7586],{47586:e=>{e.exports=JSON.parse('{"slug":"sankcii-ssha-platezhnaya-set-a7","locale":"ko","title":"미국이 A7 결제망의 수백 개 회사를 통한 은행 송금 금지를 제안했습니다","description":"미 재무부는 시월 1일 A7을 범죄조직으로 지정하고 하위 대리업체를 통한 은행 송금 금지를 제안했습니다. 수입에 미치는 영향을 살펴봅니다.","blocks":[{"id":"b001","kind":"paragraph","text":"미 재무부는 2026년 시월 1일 러시아 결제망 A7을 중대한 초국가적 범죄조직으로 지정했습니다. 동시에 산하 금융범죄단속망 FinCEN은 A7 하위 대리업체가 관여하는 모든 송금을 미국 은행에 금지하자고 제안했습니다. 하위 대리업체란 러시아 고객의 결제를 처리하기 위해 이 결제망이 사용하는 해외 위장회사를 말합니다."},{"id":"b002","kind":"paragraph","text":"A7은 2024년 몰도바 사업가 일란 쇼르와 프롬스뱌지방크가 만들었습니다. 송금 수수료는 0,3%이며 루블에 가치를 연동한 디지털 코인 A7A5 스테이블코인도 발행합니다. A7의 러시아 부문과 스테이블코인은 2025년 팔월부터 미국 제재 대상이었지만 결제는 해외 회사를 통해 계속됐습니다. 미국 당국은 이 결제망을 이란과도 연결하며 이란 중앙은행과 혁명수비대가 사용했다고 주장합니다. FinCEN의 금지안 자체는 러시아 자금세탁 방지법에 근거합니다."},{"id":"b003","kind":"paragraph","text":"A7은 규모가 큽니다. UAE\xb7홍콩\xb7튀르키예\xb7키르기스스탄 등에서 수백 개 하위 대리업체가 활동하며 83개국 약 435개 은행에 계좌를 두고 있습니다. 2025년 일월부터 2026년 유월까지 달러 결제만 $17십억 이상 처리했습니다. 이는 거래의 일부입니다. 결제망은 2026년 일월까지 누적 송금액이 7,5조 루블이라고 주장했습니다. 프롬스뱌지방크는 2025년 상반기 러시아 대외무역의 거의 12%가 A7을 통했다고 추정했습니다. FinCEN도 2025년 전체 기준 거의 13%라는 비슷한 수치를 제시합니다."},{"id":"b004","kind":"paragraph","text":"미국이 다른 나라의 결제를 막을 수 있는 이유는 무엇일까요? 서로 다른 국가 은행 간 달러 송금은 거의 항상 미국 은행 계좌를 거칩니다. 택배가 분류센터를 지나는 것과 같습니다. 발송인과 수취인이 다른 나라에 살아도 센터가 받지 않으면 도착하지 않습니다. 이런 계좌를 환거래계좌라고 합니다. 금지는 A7 하위 대리업체를 이 센터에서 차단합니다. 영향은 달러에만 그치지 않을 수 있습니다. 대리업체 계좌를 가진 외국 은행들도 제재를 받을 위험 때문에 통화와 관계없이 계좌를 닫는 편을 택할 수 있습니다. 전체 업체 명단은 은행에 비공개로 전달되고 계속 추가됩니다."},{"id":"b005","kind":"paragraph","text":"A7은 기업과 거래하므로 제재가 일반인의 지갑에 직접 영향을 주지는 않습니다. 경로는 수입가격을 통한 간접 영향입니다. 결제 장벽이 늘 때마다 해외 송금이 느리고 비싸지며 기업은 그 비용을 상품가격에 반영합니다. 가격이 얼마나 오를지는 추정할 수 없습니다. A7은 2025년에도 미국 제재를 받았지만 새로운 회사들을 통해 계속 운영됐습니다."},{"id":"b006","kind":"paragraph","text":"FinCEN 규칙은 아직 초안이며 공개 후 의견수렴 기간은 30일입니다. 미 재무부는 다른 나라와 은행이 동참하기를 기대하지만 실제 동참 여부는 알 수 없습니다. 수입 가전\xb7부품 구매자가 이 소식 때문에 미리 사재기할 필요는 없습니다. 영향은 여러 달에 걸쳐 루블 환율 움직임과 섞여 나타납니다. 그렇다고 결제망에 대한 타격이 무관하다고 볼 수도 없습니다. 비싸진 결제 비용은 결국 상품가격에 들어가기 때문입니다."},{"id":"b007","kind":"heading","text":"A7 결제망은 무엇인가요?"},{"id":"b008","kind":"paragraph","text":"2024년 일란 쇼르와 프롬스뱌지방크가 만든 국제송금 체계입니다. 해외 위장회사를 통해 러시아 기업의 결제를 처리하고 0,3% 수수료를 받으며 루블 연동 스테이블코인 A7A5를 발행합니다."},{"id":"b009","kind":"heading","text":"미국은 2026년 시월 A7에 어떤 제재를 가했나요?"},{"id":"b010","kind":"paragraph","text":"미 재무부는 2026년 시월 1일 A7을 초국가적 범죄조직으로 지정했습니다. FinCEN은 83개국 약 435개 은행에 계좌를 가진 수백 개 하위 대리업체를 통한 미국 은행의 송금 금지를 제안했습니다."},{"id":"b011","kind":"heading","text":"A7 제재로 수입품이 비싸지나요?"},{"id":"b012","kind":"paragraph","text":"그럴 수 있지만 규모는 알 수 없습니다. A7은 러시아 대외무역의 거의 12–13%를 처리했고 새로운 장벽마다 결제가 느려지고 비싸집니다. 기업은 이 비용을 상품가격에 반영합니다."}],"sources":[{"label":"미국이 A7 결제시스템을 제재했습니다","url":"https://www.kommersant.ru/doc/8991793"},{"label":"미국이 A7의 수백 개 해외 회사를 통한 결제 금지를 준비합니다","url":"https://thebell.io/ssha-gotovyat-zapret-na-platezhi-cherez-sotni-zarubezhnykh-kompaniy-a7-po-otsenke-psb-cherez-etu-set-shlo-pochti-12-vneshney-torgovli-rossii"},{"label":"Proposal of Special Measure Regarding A7 Network Sub-Agents","url":"https://www.fincen.gov/system/files/2026-10/9714-A7-NETWORK-NPRM.pdf"}],"sourceBodySha256":"e928692ceb98a757973abed5533e72f30df7536893758054b08fc807c779360a"}')}}]);